Compute the month-end dates from the headers in I1:K1. For each department in G2:G6, count records created on or before that month-end and not closed on or before that month-end. Write the resulting integer counts into I2:K6.

```python
import shutil
import openpyxl
import calendar
import re
from datetime import datetime, date

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title]

def as_date(value):
    if value is None:
        return None
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if isinstance(value, str):
        s = value.strip()
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d", "%m/%d/%Y", "%d-%b-%Y"):
            try:
                return datetime.strptime(s, fmt).date()
            except ValueError:
                pass
    return None

# Parse month-end dates from headers I1:K1, with a deterministic fallback.
month_names = {name.lower(): i for i, name in enumerate(calendar.month_name) if name}
month_ends = []
for col in range(9, 12):  # I, J, K
    header = vws.cell(row=1, column=col).value
    parsed = None
    if header is not None:
        m = re.search(r"([A-Za-z]+)\s+(\d{4})", str(header))
        if m:
            mon = month_names.get(m.group(1).lower())
            year = int(m.group(2))
            if mon:
                last_day = calendar.monthrange(year, mon)[1]
                parsed = date(year, mon, last_day)
    month_ends.append(parsed)

if any(x is None for x in month_ends):
    month_ends = [date(2022, 5, 31), date(2022, 6, 30), date(2022, 7, 31)]

# Read actual record data.
records = []
for r in range(2, vws.max_row + 1):
    dept = vws.cell(row=r, column=2).value
    created = as_date(vws.cell(row=r, column=3).value)
    closed = as_date(vws.cell(row=r, column=4).value)

    if dept is None and created is None:
        continue

    dept = str(dept).strip() if dept is not None else None
    records.append((dept, created, closed))

# Departments to report are in G2:G6.
departments = []
for r in range(2, 7):
    d = vws.cell(row=r, column=7).value
    departments.append(str(d).strip() if d is not None else None)

# Fill answer region I2:K6.
for i, dept in enumerate(departments):
    row = 2 + i
    for j, month_end in enumerate(month_ends):
        col = 9 + j
        count = 0

        if month_end is not None:
            for rec_dept, created, closed in records:
                if rec_dept != dept:
                    continue
                if created is None or created > month_end:
                    continue
                if closed is None or closed > month_end:
                    count += 1

        ws.cell(row=row, column=col).value = count
        print(f"row={row}, col={col}, dept={dept}, month_end={month_end}, count={count}")

wb.save(OUT)
